import re


_PHMSA_CONTEXT_RE = re.compile(
    r"\b(?:PHMSA|Pipeline and Hazardous Materials Safety Administration)\b",
    re.IGNORECASE,
)

_OPENING_PATTERNS = [
    # Most common form: "From <date clause> ... a representative(s) ..."
    re.compile(
        r"\b(From\s+.+?)(?:\s+of\s+the\s+(?:on-site\s+)?inspection)?\s*,\s*(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(From\s+.+?)(?:\s+of\s+the\s+(?:on-site\s+)?inspection)?\s+(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    # "On various dates between <date> and <date>, a representative(s) ..."
    re.compile(
        r"\b(On\s+various dates between\s+.+?)\s*,\s*(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(On\s+various dates between\s+.+?)\s+(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    # Less common but still an opening clause.
    re.compile(
        r"\b(Between\s+.+?)\s*,\s*(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(Between\s+.+?)\s+(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(During\s+.+?)\s*,\s*(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(During\s+.+?)\s+(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(On\s+.+?)\s*,\s*(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(On\s+.+?)\s+(?:a|an|the|one)?\s*(?:representative|representatives)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    # Fallback when the opener names PHMSA directly instead of a representative.
    re.compile(
        r"\b(From\s+.+?)\s*,\s*(?:PHMSA(?:['’]s)?|the Pipeline and Hazardous Materials Safety Administration)\b.*?\b(?:inspected|investigated|reviewed|conducted)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(From\s+.+?)\s+(?:PHMSA(?:['’]s)?|the Pipeline and Hazardous Materials Safety Administration)\b.*?\b(?:inspected|investigated|reviewed|conducted)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(On\s+.+?)\s*,\s*(?:PHMSA(?:['’]s)?|the Pipeline and Hazardous Materials Safety Administration)\b.*?\b(?:inspected|investigated|reviewed|conducted)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(
        r"\b(On\s+.+?)\s+(?:PHMSA(?:['’]s)?|the Pipeline and Hazardous Materials Safety Administration)\b.*?\b(?:inspected|investigated|reviewed|conducted)\b",
        re.IGNORECASE | re.DOTALL,
    ),
]


def rule_phmsa_inspection_date_range(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def make_span(text: str, src: dict | None = None) -> dict:
            span = {"text": norm(text)}
            if src:
                for key in ("page_no", "paragraph_no", "line_no"):
                    if key in src:
                        span[key] = src[key]
            return span

        def scan(text: str, src: dict | None = None) -> list[dict] | None:
            text = norm(text)
            if not text or not _PHMSA_CONTEXT_RE.search(text):
                return None

            for pat in _OPENING_PATTERNS:
                match = pat.search(text)
                if match:
                    return [make_span(match.group(1), src)]
            return None

        # The answer is almost always in the early opening paragraph(s), so search
        # the structured containers from most local to least local.
        for source_key, limit in (("paragraphs", 16), ("lines", 48), ("pages", 2)):
            items = [s for s in (doc.get(source_key) or []) if isinstance(s, dict)]
            for item in items[:limit]:
                found = scan(item.get("text") or "", item)
                if found:
                    return found

        text = doc.get("text") or ""
        if isinstance(text, str):
            found = scan(text[:6000], None)
            if found:
                return found

        return []
    except Exception:
        return []

import re


_MONTHS = (
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
)
_MONTH_RE = "|".join(_MONTHS)

_MONTH_DAY_RE = rf"(?:{_MONTH_RE})\s+\d{{1,2}}(?:,\s*\d{{4}})?"
_DAY_YEAR_RE = r"(?:\d{1,2}(?:,\s*\d{4})?)"
_MONTH_YEAR_RE = rf"(?:{_MONTH_RE})\s+\d{{4}}"
_DATE_RE = rf"(?:{_MONTH_DAY_RE}|\d{{1,2}}/\d{{1,2}}/\d{{2,4}}|\d{{1,2}}-\d{{1,2}}-\d{{2,4}})"

_RANGE_PATTERNS = [
    # The most common opener: "From <date> to/through <date>, ... inspected ..."
    re.compile(
        rf"\bFrom\s+({_DATE_RE})(?:,\s*)?\s+(?:to|through|[-–])\s+({_DATE_RE}|{_DAY_YEAR_RE})",
        re.IGNORECASE,
    ),
    # Openers that describe the inspection as occurring on "various dates between".
    re.compile(
        rf"\bOn\s+various dates between\s+({_MONTH_YEAR_RE}|{_DATE_RE})\s+and\s+({_MONTH_YEAR_RE}|{_DATE_RE})",
        re.IGNORECASE,
    ),
    # Openers like "Between July and October 2021, a representative ... inspected ...".
    re.compile(
        rf"\bBetween\s+({_MONTH_RE})\s+and\s+({_MONTH_RE})\s+\d{{4}}",
        re.IGNORECASE,
    ),
    # Openers like "From/For the weeks of July 29 to August 2, 2024, and ...".
    re.compile(
        r"\b(?:From|For)\s+the\s+weeks?\s+of\s+(.+?)(?=,\s*(?:a|an|the|one|representative|representatives|PHMSA)\b|\s+(?:a|an|the|one|representative|representatives|PHMSA)\b)",
        re.IGNORECASE,
    ),
    # Openers like "During the September 20 through 24, 2021 field inspection".
    re.compile(
        rf"\bDuring\s+the\s+((?:{_MONTH_RE})\s+\d{{1,2}}\s+(?:to|through|[-–])\s+(?:(?:{_MONTH_RE})\s+)?\d{{1,2}}(?:,\s*\d{{4}})?)\s+(?:field\s+)?inspection\b",
        re.IGNORECASE,
    ),
    # Openers like "During PHMSA's field inspection on April 10, 2025".
    re.compile(
        rf"\bDuring\s+(?:PHMSA(?:'s)?\s+)?(?:on-site\s+)?(?:field\s+)?inspection\s+on\s+({_DATE_RE})",
        re.IGNORECASE,
    ),
    # Single-date openers: "On May 10, 2023, ... inspected ..."
    re.compile(
        rf"\bOn\s+({_DATE_RE})",
        re.IGNORECASE,
    ),
]

_FALLBACK_OPENING_RE = re.compile(
    r"^\s*(?:From|On|During)\b.{0,260}?\binspect(?:ed|ion)\b",
    re.IGNORECASE | re.DOTALL,
)


def rule_phmsa_inspection_date_range(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def make_span(text: str, src: dict | None = None) -> dict:
            span = {"text": norm(text)}
            if src:
                for key in ("page_no", "line_no", "paragraph_no"):
                    if key in src:
                        span[key] = src[key]
            return span

        def maybe_add_span(text: str, src: dict | None = None) -> list[dict] | None:
            text = norm(text)
            if not text:
                return None

            for pat in _RANGE_PATTERNS:
                match = pat.search(text)
                if not match:
                    continue
                if pat is _RANGE_PATTERNS[2]:
                    return [make_span(match.group(0), src)]
                if pat is _RANGE_PATTERNS[3]:
                    return [make_span(match.group(1), src)]
                if pat is _RANGE_PATTERNS[4]:
                    return [make_span(match.group(1), src)]
                if pat is _RANGE_PATTERNS[5]:
                    return [make_span(match.group(1), src)]
                # Preserve the full matched range phrase for the other opener types.
                return [make_span(match.group(0), src)]

            fallback = _FALLBACK_OPENING_RE.search(text)
            if fallback and re.search(r"\b(?:PHMSA|representative|representatives|inspector)\b", fallback.group(0), re.IGNORECASE):
                return [make_span(fallback.group(0), src)]
            return None

        # Search the most local/topical containers first.
        for source_key, limit in (("pages", 2), ("paragraphs", 12), ("lines", 40)):
            items = [s for s in (doc.get(source_key) or []) if isinstance(s, dict)]
            for item in items[:limit]:
                found = maybe_add_span(item.get("text") or "", item)
                if found:
                    return found

        # Fallback to the top of the raw text if the document was split unusually.
        text = doc.get("text") or ""
        head = text[:4000] if isinstance(text, str) else ""
        found = maybe_add_span(head, None)
        if found:
            return found

        return []
    except Exception:
        return []

        current: list[str] = []
        for line in page_lines + [""]:
            if line.strip():
                current.append(line)
                continue
            if current:
                para_no += 1
                paragraphs.append(
                    {
                        "page_no": page_idx,
                        "paragraph_no": para_no,
                        "paragraph_index": global_para_idx,
                        "text": "\n".join(current).strip(),
                    }
                )
                global_para_idx += 1
                current = []

    return {
        "doc_name": doc_name,
        "doc_path": str(path.resolve()),
        "text": raw,
        "pages": pages,
        "paragraphs": paragraphs,
        "lines": lines,
    }


def _load_rule_fn(rule_file: Path):
    spec = importlib.util.spec_from_file_location(f"_rule_mod_{rule_file.stem}", str(rule_file))
    if spec is None or spec.loader is None:
        raise ValueError(f"Failed to load rule module: {rule_file}")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    for name, value in vars(mod).items():
        if name.startswith("rule_") and callable(value):
            return value
    raise ValueError(f"No function starting with 'rule_' found in {rule_file}")


def _coerce_span(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, str):
        text = entry.strip()
        return {"text": text} if text else None
    if not isinstance(entry, dict):
        return None
    text = entry.get("text")
    if text is None:
        return None
    text = str(text)
    if not text.strip():
        return None
    coerced = dict(entry)
    coerced["text"] = text
    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


def _parse_done_output(text: str) -> str | None:
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("AGENTIC_RULE_FULL_DATA_DONE"):
            rest = line[len("AGENTIC_RULE_FULL_DATA_DONE") :].strip()
            if rest.startswith("report="):
                return rest[len("report=") :].strip()
    return None


def _parse_codex_events(jsonl_text: str) -> dict[str, Any]:
    usage_totals = {
        "input_tokens": 0,
        "output_tokens": 0,
        "cached_input_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    thread_id: str | None = None
    error_message: str | None = None
    event_count = 0

    for raw_line in jsonl_text.splitlines():
        raw_line = raw_line.strip()
        if not raw_line:
            continue
        try:
            event = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        event_count += 1
        if event.get("type") == "thread.started":
            thread_id = event.get("thread_id")
        elif event.get("type") == "turn.completed":
            usage = event.get("usage") or {}
            for key in usage_totals:
                usage_totals[key] += int(usage.get(key) or 0)
        elif event.get("type") in {"error", "turn.failed"}:
            error_message = event.get("message") or str(event.get("error") or "")

    return {
        "usage_totals": usage_totals,
        "thread_id": thread_id,
        "error_message": error_message,
        "event_count": event_count,
    }


def _load_json(path: Path, default: Any) -> Any:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def _relpath(path: Path) -> str:
    try:
        return str(path.relative_to(_ROOT))
    except ValueError:
        return str(path)


def _ledger_load(ledger_path: Path) -> dict[str, Any]:
    return _load_json(ledger_path, {"verify_accuracy_calls": []})


def _ledger_append_verify(ledger_path: Path, entry: dict[str, Any]) -> dict[str, Any]:
    ledger = _ledger_load(ledger_path)
    calls = ledger.setdefault("verify_accuracy_calls", [])
    calls.append(entry)
    _write_json(ledger_path, ledger)
    return ledger


def _manifest_docs(manifest: dict[str, Any]) -> dict[str, Path]:
    return {
        entry["doc_name"]: Path(entry["doc_path"])
        for entry in manifest.get("documents", [])
    }


